def road_address(addr):
    """지도 검색용: '…로 300, 304호 (범어동, 상가)' → '…로 300' (동·호수·건물명 제거)."""
    a = re.split(r'[,(]', addr or '')[0]
    a = re.sub(r'\s+\S*(?:\d+호|\d+층|층)$', '', a.strip())
    return a.strip()

def load_assets():
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(EMBEDDED_ASSETS.encode()))) as z:
        return {n: z.read(n) for n in z.namelist()}


def region_parts(region):
    text = str(region or '').strip()
    token = re.search(r'(?:서울|부산|대구|인천|광주|대전|울산|세종)(?:특별자치시|특별시|광역시)?|경상북도|경상남도|전북특별자치도|전라북도|전라남도|강원특별자치도|강원도|충청북도|충청남도|경기도|제주특별자치도|경북|경남|전북|전남|충북|충남|제주', text)
    province = token.group() if token else ''
    province = '대구광역시' if province.startswith('대구') else '경상북도' if province in ('경북', '경상북도') else province
    rest = text[:token.start()] + ' ' + text[token.end():] if token else text
    district = re.search(r'([가-힣]+(?:시|군|구))(?=\s|[가-힣]+동|$)', rest)
    dong = re.search(r'([가-힣0-9]+동)(?=\s|$)', rest)
    return province, district.group(1) if district else '', dong.group(1) if dong else ''


def suggest_region(conditions, facilities):
    province, district, dong = region_parts(conditions.get('region'))
    if not dong:
        return None
    matches = {(f['province'], f['district'], f['dong']) for f in facilities if f['dong'] == dong}
    if len(matches) != 1:
        return None
    correct_province, correct_district, correct_dong = next(iter(matches))
    if (not province or province == correct_province) and (not district or district == correct_district):
        return None
    return f'{correct_province} {correct_district} {correct_dong}'



THERAPY_KEYS = [('언어', '언어'), ('감각', '감각'), ('운동', '운동'), ('미술', '미술'), ('음악', '음악'), ('놀이', '놀이'), ('행동', '행동')]

def confirmed_rank(conditions, f):
    """정보공개청구 회신에 실제 서비스 영역·운영요일이 있으면 그것으로 먼저 정렬 (0 맞음, 1 모름, 2 안 맞음)."""
    wanted = [k for w, k in THERAPY_KEYS if w in (conditions.get('therapy') or '')]
    rank = 1
    if wanted and f.get('confirmedTherapy'):
        rank = 0 if any(k in f['confirmedTherapy'] for k in wanted) else 2
    t = conditions.get('time') or ''
    if rank < 2 and f.get('hoursDays') and any(w in t for w in ('토요일', '주말')):
        rank = rank if '토' in f['hoursDays'] else 2
    return rank

def select_candidates(conditions, facilities):
    """같은 시군구 기관 중: 회신상 요청 분야·주말 불가 기관은 뒤로, 그다음 ① 입력한 동(없으면 시군구) 중심에서 가까운 순
    ② 거리가 같으면(같은 건물 등) 품질등급 A·B·C를 순위 차이 없이 먼저. 품질등급은 화면에 표시하지 않는다."""
    province, district, dong = region_parts(conditions.get('region'))
    if not district and not dong:
        return []
    rows = [f for f in facilities if (not province or f['province'] == province) and
            (f['district'] == district if district else f['dong'] == dong)]
    if not district and len({(f['province'], f['district']) for f in rows}) > 1:
        return []
    pts = [f for f in rows if dong and f['dong'] == dong and f.get('lat') is not None] or [f for f in rows if f.get('lat') is not None]
    center = (sum(f['lat'] for f in pts) / len(pts), sum(f['lng'] for f in pts) / len(pts)) if pts else None
    def dist(f):
        if center is None or f.get('lat') is None:
            return 9e9
        return ((f['lat'] - center[0]) * 111.0) ** 2 + ((f['lng'] - center[1]) * 90.0) ** 2
    return sorted(rows, key=lambda f: (1 if confirmed_rank(conditions, f) == 2 else 0,
                                       round(dist(f) ** 0.5, 1),  # ① 가까운 순 (0.1km 단위)
                                       0 if f.get('grade') in ('A', 'B', 'C') else 1))[:3]  # ② 같은 거리면 A·B·C 먼저

def normalize(text):
    return re.sub(r'[\s,.。]', '', text)


def extract_demo(text, cases, facilities=None):
    for case in cases:
        if normalize(text) == normalize(case['input']):
            return dict(case['conditions']), '기록된 시험 사례'
    age = re.search(r'(\d{1,2})\s*(살|세)', text)
    province, district, dong = region_parts(text)
    if not district and facilities:  # '중구에 살아요'처럼 조사가 붙은 시군구 이름 찾기
        compact = re.sub(r'\s+', '', text)
        names = {}
        for f in facilities:
            if province and f['province'] != province:
                continue
            d = f['district']
            names.setdefault(d, set()).add(f['province'])
            if d.endswith(('시', '군')) and len(d) >= 3:
                names.setdefault(d[:-1], set()).add(f['province'])
        found = sorted({k for k in names if k in compact}, key=len, reverse=True)
        if found:
            full = next((d for d in {f['district'] for f in facilities} if d == found[0] or d[:-1] == found[0]), found[0])
            provs = names[found[0]]
            if len(provs) == 1:
                district = full
                province = province or next(iter(provs))
    if not dong and facilities:
        compact=re.sub(r'\s+', '', text)
        known={f['dong'] for f in facilities if f.get('dong') and f['dong'] in compact}
        if len(known)==1:
            dong=next(iter(known))
    therapies = [label for pattern, label in [(r'언어\s*(치료|재활)', '언어치료'),
                 (r'감각\s*(통합|발달)', '감각통합·감각발달'), (r'운동\s*(치료|재활)', '운동치료'),
                 (r'미술\s*치료', '미술치료')] if re.search(pattern, text)]
    times = [word for word in ['평일', '오전', '오후', '토요일', '일요일', '주말'] if word in text]
    hour = re.search(r'(\d{1,2})\s*시\s*(이후|전|부터)?', text)
    if hour:
        times.append(hour.group())
    traits=[]
    if re.search(r'초등학교?\s*저학년|초등\s*저학년',text):
        traits.append('초등학교 저학년(정확한 나이 미기재)')
    if re.search(r'등교.{0,9}거부|학교.{0,6}가(?:기)?\s*싫|학교.{0,6}안\s*가',text):
        traits.append('등교 거부를 보호자가 언급함')
    if re.search(r'아이들.{0,12}사이|친구.{0,12}관계',text):
        traits.append('또래 관계 원인은 보호자의 추측으로 미확인')
    return {'age': age.group() if age else '정보 없음',
            'therapy': ', '.join(therapies) or '전문가 상담을 통해 치료영역 확인 필요',
            'traits': ' · '.join(traits) or '정보 없음',
            'time': ' · '.join(times) or '정보 없음',
            'region': ' '.join(x for x in (province, district, dong) if x) or '정보 없음'}, '단순 규칙 기반 시연'



def candidate_popup(no, f):
    """지도 마커 팝업: 카드형 (번호·기관명·주소·전화·치료 분야·운영시간·카카오맵 링크)."""
    def badge(text, color):
        return f'<span style="background:{color};color:#fff;border-radius:10px;padding:1px 7px;font-size:11px">{text}</span>'
    if f.get('confirmedTherapy'):
        therapy = f"{f['confirmedTherapy']} {badge('확인됨·' + f.get('confirmSource', '') + ' 회신', '#2E7D32')}"
    else:
        therapy = f"{f['therapy']} {badge(f['therapyStatus'], '#E08E0B' if f['therapyStatus'] == '추정' else '#8A8A8A')}"
    hours = (f"{f.get('hoursDays', '')} {f.get('hoursTime', '')}".strip()) or badge('확인 필요', '#8A8A8A')
    link = 'https://map.kakao.com/link/search/' + quote(road_address(f['address']))
    return f"""<div style="font-family:'Apple SD Gothic Neo',sans-serif;width:260px">
      <div style="background:#29385F;color:#fff;padding:8px 10px;border-radius:6px 6px 0 0;font-weight:bold">{no}. {f['name']}</div>
      <table style="font-size:12px;width:100%;border-collapse:collapse;margin-top:6px">
        <tr><td style="color:#777;width:62px">주소</td><td>{f['address']}</td></tr>
        <tr><td style="color:#777">전화</td><td>{f['phone']}</td></tr>
        <tr><td style="color:#777">치료 분야</td><td>{therapy}</td></tr>
        <tr><td style="color:#777">운영시간</td><td>{hours}</td></tr>
      </table>
      <div style="margin-top:8px"><a target="_blank" href="{link}" style="font-size:12px;color:#29385F">카카오맵에서 길찾기 ↗</a></div></div>"""


def show_candidate_map(st, candidates):
    """후보 3곳을 번호 원형 마커로 지도에 표시하고, 지도에 못 넣은 기관을 안내."""
    try:
        import folium
        from folium.features import DivIcon
        from streamlit_folium import st_folium
    except ImportError:
        st.caption('지도 표시에는 folium·streamlit-folium 설치가 필요합니다.')
        return
    placed = [(i, f) for i, f in enumerate(candidates, 1) if f.get('lat') is not None]
    if placed:
        m = folium.Map(location=[placed[0][1]['lat'], placed[0][1]['lng']], zoom_start=14, tiles='OpenStreetMap')
        for i, f in placed:
            folium.Marker([f['lat'], f['lng']], popup=folium.Popup(candidate_popup(i, f), max_width=300), tooltip=f"{i}. {f['name']}",
                icon=DivIcon(icon_size=(30, 30), icon_anchor=(15, 15),
                    html=f'<div style="background:#29385F;color:#fff;border:2px solid #fff;border-radius:50%;width:28px;height:28px;'
                         f'text-align:center;line-height:26px;font-weight:bold;box-shadow:0 1px 4px rgba(0,0,0,.4)">{i}</div>')).add_to(m)
        if len(placed) > 1:
            m.fit_bounds([[f['lat'], f['lng']] for _, f in placed], padding=(30, 30), max_zoom=16)
        st_folium(m, height=420, use_container_width=True, returned_objects=[], key='candidate_map')
    notes = [f"{i}. {f['name']}: 위치 미확인 (주소를 좌표로 바꾸지 못함)" for i, f in enumerate(candidates, 1) if f.get('lat') is None]
    notes += [f"{i}. {f['name']}: 등록 지역과 실제 주소가 다름 (실제 주소 위치에 표시)" for i, f in enumerate(candidates, 1) if f.get('geoStatus') == '지역 불일치 확인 필요']
    st.caption('지도 안내 — ' + (' / '.join(notes) if notes else '후보 모두 등록 주소 위치에 표시했습니다.') + ' 좌표: 카카오 주소 변환.')


